tests.code:
cases = {1: "remote chance", 5: "remote chance", 10: "highly unlikely", 20: "highly unlikely",
         30: "unlikely", 40: "realistic possibility", 49: "realistic possibility",
         55: "likely", 75: "likely", 85: "highly likely", 95: "almost certain", 99: "almost certain"}
for value, term in cases.items():
    assert yardstick(value) == term, (value, yardstick(value))

for bad in (-1, 101, 12.5, "60"):
    try:
        yardstick(bad)
    except ValueError:
        continue
    raise AssertionError(f"no ValueError for {bad!r}")

exercises.starter:
def yardstick(percent):
    if percent > 50:
        return "likely"
    return "unlikely"
